fees=intro('SIMPLE, TRANSPARENT FEES','More clarity.<br>Right from the start.','Find the published hourly fee for your class and subject. Start with a free demo to explore the fit.')+f'''<section class="section section-first"><div class="container pricing-layout"><div class="pricing-main"><div class="pricing-header"><h2>Tuition fees</h2><div class="segmented" role="group" aria-label="Choose country"><button type="button" class="selected" data-country="india" aria-pressed="true">India · INR</button><button type="button" data-country="canada" aria-pressed="false">Canada · CAD</button></div></div><div id="india-pricing" class="price-panel"><p class="muted">Hourly rates for students in India</p><div class="table-scroll"><table><thead><tr><th scope="col">Class</th><th scope="col">Subject</th><th scope="col">Per hour</th></tr></thead><tbody>{''.join(f'<tr><td>{a}</td><td>{b}</td><td><strong>{c}</strong></td></tr>' for a,b,c in fee_rows)}</tbody></table></div></div><div id="canada-pricing" class="price-panel" hidden><p class="muted">Hourly rates for students in Canada</p><div class="canada-price">{ico('globe')}<div><span>All subjects · All grades</span><p>CAD 15 <small>/ hour</small></p></div></div><p>Contact us to confirm subject availability and a schedule that works across time zones.</p></div><p class="pricing-note">Fees are per hour. Confirm your class schedule and payment arrangements with the team before enrolling.</p></div><aside class="demo-aside"><span class="round-icon">{ico('spark')}</span><div class="eyebrow">START WITH A CONVERSATION</div><h2>A free demo.<br>A fresh perspective.</h2><p>Meet your tutor and see how learning with us can help.</p><ul class="check-list"><li>{ico('check')} Explore your subject</li><li>{ico('check')} Discuss your learning goals</li><li>{ico('check')} Find the right next step</li></ul>{button('Request a free demo')}<a class="text-link" href="Contact.html">Ask about fees {ico('arrow')}</a></aside></div></section>'''+faq_block()+cta()
